--
-- Name: v_classement_etape; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_classement_etape AS
 SELECT r.nomrallye,
    r.annee,
    r.numetape,
    et.typeetape,
    r.numequipage,
    e.nomequipe,
    p.numeroorga,
    r.dureeheure,
    r.disqualifiee,
        CASE
            WHEN (NOT r.disqualifiee) THEN rank() OVER (PARTITION BY r.nomrallye, r.annee, r.numetape, r.disqualifiee ORDER BY r.dureeheure)
            ELSE NULL::bigint
        END AS rang
   FROM (((public.resultat r
     JOIN public.etape et ON ((((et.nomrallye)::text = (r.nomrallye)::text) AND (et.annee = r.annee) AND (et.numetape = r.numetape))))
     JOIN public.equipage e ON ((((e.nomrallye)::text = (r.nomrallye)::text) AND (e.annee = r.annee) AND (e.numequipage = r.numequipage))))
     JOIN public.pilote p ON ((((p.nomrallye)::text = (r.nomrallye)::text) AND (p.annee = r.annee) AND (p.numequipage = r.numequipage))));


