    nommarque character varying(50) NOT NULL,
    CONSTRAINT vehicule_cylindree_check CHECK ((cylindree > 0)),
    CONSTRAINT vehicule_type_check CHECK (((type)::text = ANY ((ARRAY['Auto'::character varying, 'Camion'::character varying, 'Moto'::character varying])::text[])))
);


--
-- Name: v_participation; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_participation AS
 SELECT c.nomrallye,
    c.annee,
    c.numequipage,
    co.numconcurrent,
    co.nom,
    co.prenom,
    co.nompays AS nationalite,
    e.nomequipe,
    eq.typeequipe,
    p.numeroorga,
    v.numeroserie,
    v.nommarque,
    v.type AS typevehicule
   FROM (((((public.compose c
     JOIN public.concurrent co ON ((co.numconcurrent = c.numconcurrent)))
     JOIN public.equipage e ON ((((e.nomrallye)::text = (c.nomrallye)::text) AND (e.annee = c.annee) AND (e.numequipage = c.numequipage))))
     JOIN public.equipe eq ON (((eq.nomequipe)::text = (e.nomequipe)::text)))
     JOIN public.pilote p ON ((((p.nomrallye)::text = (e.nomrallye)::text) AND (p.annee = e.annee) AND (p.numequipage = e.numequipage))))
     JOIN public.vehicule v ON (((v.numeroserie)::text = (p.numeroserie)::text)));


--
-- Name: v_rallye_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_rallye_stats AS
 SELECT nomrallye,
    annee,
    ( SELECT count(*) AS count
           FROM public.etape et
          WHERE (((et.nomrallye)::text = (r.nomrallye)::text) AND (et.annee = r.annee))) AS nbetapes,
    ( SELECT count(*) AS count
           FROM public.equipage e
          WHERE (((e.nomrallye)::text = (r.nomrallye)::text) AND (e.annee = r.annee))) AS nbequipages,
    ( SELECT count(*) AS count
           FROM public.compose c
          WHERE (((c.nomrallye)::text = (r.nomrallye)::text) AND (c.annee = r.annee))) AS nbconcurrents
   FROM public.rallye r;


