--
-- Name: v_etape_pays _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.v_etape_pays AS
 SELECT et.nomrallye,
    et.annee,
    et.numetape,
    et.typeetape,
    et.villedepart,
    et.villearrivee,
    et.distance,
    string_agg((t.nompays)::text, ', '::text ORDER BY (t.nompays)::text) AS pays
   FROM (public.etape et
     LEFT JOIN public.traverse t ON ((((t.nomrallye)::text = (et.nomrallye)::text) AND (t.annee = et.annee) AND (t.numetape = et.numetape))))
  GROUP BY et.nomrallye, et.annee, et.numetape;


